// Nos quedamos con los PDF y los Word (las imágenes de firma y demás adjuntos se descartan), cada uno con su propio nombre, y los contamos
for (const item of $input.all()) {
  const documentos = {};
  let pdfs = 0, docs = 0;

  for (const archivo of Object.values(item.binary || {})) {
    const nombre = (archivo.fileName || '').toLowerCase();
    const mime = (archivo.mimeType || '').toLowerCase();

    if (mime === 'application/pdf' || nombre.endsWith('.pdf')) {
      documentos[`documento_pdf_${pdfs}`] = { ...archivo, mimeType: 'application/pdf' };
      pdfs++;
    } else if (mime === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || mime === 'application/msword'
      || nombre.endsWith('.docx') || nombre.endsWith('.doc')) {
      documentos[`documento_docx_${docs}`] = archivo;
      docs++;
    }
  }

  if (item.binary) item.binary = documentos;
  item.json.numPDFs = pdfs;
  item.json.numDOCX = docs;
}

return $input.all();

// Pasan todos los documentos (PDF directos o convertidos desde Word); a los convertidos les damos nombre .pdf
return $input.all().map((item, i) => ({
  json: {
    ...item.json,
    pdf_filename: item.json.pdf_filename || String(item.json.docx_filename || '').replace(/\.docx?$/i, '.pdf')
  },
  binary: item.binary,
  pairedItem: i
}));

// Un elemento por documento: todos los PDF del correo o, si no hay ninguno, todos los Word.
// Sin documentos sale un elemento vacío para que vaya a la rama de error
const resultado = [];

$input.all().forEach((item, i) => {
  const binarios = item.binary || {};
  const pdfs = Object.keys(binarios).filter(clave => clave.startsWith('documento_pdf'));
  const esPdf = pdfs.length > 0;
  const documentos = esPdf ? pdfs : Object.keys(binarios).filter(clave => clave.startsWith('documento_docx'));

  documentos.forEach((clave, n) => {
    const archivo = binarios[clave];
    resultado.push({
      json: {
        ...item.json,
        pdf_filename: esPdf ? archivo.fileName : '',
        docx_filename: esPdf ? '' : archivo.fileName,
        doc_indice: n + 1,
        doc_total: documentos.length
      },
      binary: esPdf ? { documento_pdf: archivo } : { documento_docx: archivo },
      pairedItem: i
    });
  });

  if (!documentos.length) {
    resultado.push({ json: { ...item.json, pdf_filename: '', docx_filename: '' }, pairedItem: i });
  }
});

return resultado;

const items = $input.all();
// Nodo Code para procesamiento más robusto
const body = items[0].json.body.content || '';
const targetWords = ['pedido', 'compra', 'solicitud'];

// Verifica todas las propiedades disponibles
console.log('Propiedades del item:', Object.keys(items[0].json));
console.log('Contenido completo:', JSON.stringify(items[0].json, null, 2));

// Normalizar texto para mejor detección
const cleanText = body
  .toLowerCase()
  .replace(/[^\w\s]/g, ' ') // Elimina puntuación
  .replace(/\s+/g, ' ');    // Normaliza espacios

// Detectar palabras clave como tokens completos
const tokens = cleanText.split(' ');
const matches = tokens.filter(token => targetWords.includes(token));

// Detectar también frases con "pedido" en contexto
const hasOrderContext = /(realizar|hacer|enviar|confirmar)\s+un?\s+pedido/i.test(body);

// Devolver cuerpo completo y resultado de detección
items[0].json.bodyContent = body;        // Cuerpo completo original
items[0].json.bodyLength = body.length;  // (opcional) longitud del mensaje
items[0].json.hasPedido = matches.length > 0 || hasOrderContext;// Resultado de la búsqueda
items[0].json.matches = matches;

return items;

